const { Scalekit } = require('@scalekit-sdk/node');
const fs = require('fs');
const path = require('path');

// Initialize Scalekit instance
// Note: You'll need to set these environment variables with your actual Scalekit credentials
const scalekit = new Scalekit({
  envUrl: process.env.SCALEKIT_ENV_URL || 'https://api.scalekit.com',
  apiKey: process.env.SCALEKIT_API_KEY
});

async function generatePortalLink() {
  try {
    console.log('Generating Admin Portal link for organization: org_1234567890');

    // Generate the portal link
    const result = await scalekit.organization.generatePortalLink({
      organization_id: 'org_1234567890',
      features: ['sso', 'directory_sync']
    });

    // Extract the portal link
    const portalLink = result.url;

    console.log('Portal link generated successfully!');

    // Write the link to the file
    const filePath = path.join(__dirname, 'portal_link.txt');
    fs.writeFileSync(filePath, portalLink, 'utf8');

    console.log(`Portal link saved to: ${filePath}`);
    console.log(`Link: ${portalLink}`);

  } catch (error) {
    console.error('Error generating portal link:', error.message);
    process.exit(1);
  }
}

// Run the function
generatePortalLink();

