const { ScalekitClient } = require('@scalekit-sdk/node');
const fs = require('fs');
const path = require('path');

// Initialize Scalekit client
// Note: You'll need to set these environment variables with your actual Scalekit credentials
const scalekitClient = new ScalekitClient(
  process.env.SCALEKIT_ENV_URL,
  process.env.SCALEKIT_CLIENT_ID,
  process.env.SCALEKIT_CLIENT_SECRET
);

async function generatePortalLink() {
  try {
    console.log('Generating Admin Portal link for organization: org_1234567890');

    // Generate the portal link
    const link = await scalekitClient.organization.generatePortalLink('org_1234567890');

    console.log('Portal link generated successfully!');
    console.log(`Location: ${link.location}`);
    console.log(`Expires At: ${link.expiresAt}`);

    // Write the link to the file
    const filePath = path.join(__dirname, 'portal_link.txt');
    fs.writeFileSync(filePath, link.location, 'utf8');

    console.log(`\nPortal link saved to: ${filePath}`);

  } catch (error) {
    console.error('Error generating portal link:', error.message);
    if (error.message.includes('SCALEKIT_ENV_URL')) {
      console.error('\nPlease set the following environment variables:');
      console.error('  - SCALEKIT_ENV_URL: Your Scalekit environment URL');
      console.error('  - SCALEKIT_CLIENT_ID: Your Scalekit client ID');
      console.error('  - SCALEKIT_CLIENT_SECRET: Your Scalekit client secret');
    }
    process.exit(1);
  }
}

// Run the function
generatePortalLink();

